from typing import List, Dict, Any

def validate_schema(data: Dict[str, Any], schema: Dict[str, type]) -> List[str]:
    errors = []
    for field, expected_type in schema.items():
        if field not in data:
            errors.append(f'缺少字段: {field}')
        elif not isinstance(data[field], expected_type):
            errors.append(f'{field} 类型错误: 期望 {expected_type.__name__}, 实际 {type(data[field]).__name__}')
    return errors

def parse_log_line(line):
    import re
    pattern = r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[(\w+)\] (.*)'
    match = re.match(pattern, line)
    if match:
        return {'timestamp': match.group(1), 'level': match.group(2), 'message': match.group(3)}
    return None

import os

def list_files_recursive(directory, pattern=None):
    import fnmatch
    result = []
    for root, dirs, files in os.walk(directory):
        for f in files:
            if pattern is None or fnmatch.fnmatch(f, pattern):
                result.append(os.path.join(root, f))
    return result

def rate_limiter(max_calls, period):
    import time
    calls = []
    def wrapper(func):
        def inner(*args, **kwargs):
            now = time.time()
            calls[:] = [t for t in calls if now - t < period]
            if len(calls) >= max_calls:
                raise Exception('请求过于频繁，请稍后再试')
            calls.append(now)
            return func(*args, **kwargs)
        return inner
    return wrapper
